pub const ERR_FORMAT_TIME_DIRECTIVE_UNSUPPORTED: Code = Code { id: "ERR-FORMAT-TIME-DIRECTIVE-UNSUPPORTED", level: Level::Error, title: "strftime directive in a Vega-rendered time format cannot be measured", params: &["available", "directives", "field_path", "spec"], template: "Format {spec!r} at {field_path} uses {directives}, which dbt Charts cannot render identically to what Vega paints on the axis: either it is not part of d3-time-format's directive set at all (Vega paints the literal letter), or Python renders it through the host's C locale or local timezone rather than d3's UTC/en-US output. This slot is baked onto a Vega-painted axis, whose label width is also measured from this same spec -- a mismatch here is a wrong render that looks right until the label overlaps its neighbor. Supported directives: {available}.", fix: None, hint: None };
pub const ERR_FORMAT_UNSUPPORTED: Code = Code { id: "ERR-FORMAT-UNSUPPORTED", level: Level::Error, title: "Unknown render format", params: &["format"], template: "Unknown format: {format!r}", fix: None, hint: None };
