pub const ERR_GEO_PROJECTION_REQUIRED: Code = Code { id: "ERR-GEO-PROJECTION-REQUIRED", level: Level::Error, title: "A map has no projection and no geo source to take one from", params: &["chart_id", "chart_type", "field_path", "maps_docs_url"], template: "Chart {chart_id!r} is a {chart_type} with no {field_path}, and its geo source (if any) sets none. Set `projection:` (for example `projection: mercator`) or set `geo_source:` to a source that has one. See {maps_docs_url} for the available projections.", fix: None, hint: None };
