pub const ERR_HISTOGRAM_PREAGGREGATED: Code = Code { id: "ERR-HISTOGRAM-PREAGGREGATED", level: Level::Error, title: "Histogram data looks pre-aggregated, not raw rows", params: &["chart_id", "count_fields", "field"], template: "Histogram chart {chart_id!r} received data where {field!r} forms a gapless run of whole numbers alongside unused numeric column(s) {count_fields}: this looks like pre-aggregated data (one row per bucket, e.g. `GROUP BY {field}`), not the raw, ungrouped rows a histogram bins itself. Vega-Lite would bin and count these already-counted rows again, silently discarding whatever real measure they carry. Use `type: bar` with `x: {field}` and one of {count_fields} as `y` to chart pre-aggregated data instead.", fix: None, hint: None };
