pub const ERR_TICKS_COUNT_REQUIRES_NON_LOG_SCALE: Code = Code { id: "ERR-TICKS-COUNT-REQUIRES-NON-LOG-SCALE", level: Level::Error, title: "ticks.count is not supported with log scale", params: &["chart_id"], template: "Chart {chart_id!r}: axis_y.ticks.count is not supported with scale.type: log: a target tick count on a log axis is nonsense; Vega-Lite computes log-decade ticks natively. Remove ticks.count.", fix: None, hint: None };
pub const ERR_TICKS_INTERVAL_MEASURE_AXIS: Code = Code { id: "ERR-TICKS-INTERVAL-MEASURE-AXIS", level: Level::Error, title: "ticks.time_unit is not supported on the measure axis", params: &[], template: "style.axis_y.ticks.time_unit/step is not supported: the measure axis (axis_y) is never temporal in dbt charts' cartesian model, and its tick ladder is computed from ticks.count. Use axis_y.ticks.count here; ticks.time_unit/step apply to axis_x.", fix: None, hint: None };
pub const ERR_TICKS_INTERVAL_NOT_TEMPORAL: Code = Code { id: "ERR-TICKS-INTERVAL-NOT-TEMPORAL", level: Level::Error, title: "ticks.time_unit requires a continuous temporal x-axis", params: &["field", "vl_type"], template: "style.axis_x.ticks.time_unit requires a continuous temporal x-axis, but {field!r} resolved to a {vl_type!r} scale. Force a continuous scale with axis_x.type: temporal (or axis_x.time_unit: none), or remove ticks.time_unit.", fix: None, hint: None };
pub const ERR_TICKS_STEP_NOT_QUANTITATIVE: Code = Code { id: "ERR-TICKS-STEP-NOT-QUANTITATIVE", level: Level::Error, title: "a bare ticks.step requires a quantitative x-axis", params: &["field", "remedy", "vl_type"], template: "style.axis_x.ticks.step without ticks.time_unit is a numeric tick interval, but {field!r} resolved to a {vl_type!r} scale. {remedy}", fix: None, hint: None };
pub const ERR_TICKS_TIME_UNIT_NO_CADENCE: Code = Code { id: "ERR-TICKS-TIME-UNIT-NO-CADENCE", level: Level::Error, title: "Tick time unit without a step-anchored cadence", params: &["grains", "time_unit"], template: "ticks.time_unit: {time_unit!r} has no step-anchored cadence -- only a calendar-bucketing grain ({grains}) names a VL tick interval.", fix: None, hint: None };
