pub const ERR_UNKNOWN_VARIABLE: Code = Code { id: "ERR-UNKNOWN-VARIABLE", level: Level::Error, title: "Unknown variable referenced in template", params: &["owner_name", "surface", "var_name"], template: "{surface} {owner_name!r} references unknown variable {var_name!r}. Declare it under `variables:` or fix the typo.", fix: None, hint: None };
pub const ERR_UNKNOWN_VARIABLE_OVERRIDE: Code = Code { id: "ERR-UNKNOWN-VARIABLE-OVERRIDE", level: Level::Error, title: "Caller set a variable the board does not declare", params: &["available", "variable"], template: "Variable {variable!r} is not declared by this board. Declared variables: {available}.", fix: None, hint: Some("suggest_close_variable") };
pub const ERR_UNKNOWN_WARNING_CODE: Code = Code { id: "ERR-UNKNOWN-WARNING-CODE", level: Level::Error, title: "--ignore-warning names an unregistered code", params: &["code"], template: "unknown warning code: {code!r}", fix: None, hint: None };
pub const ERR_UNPARSEABLE_SQL: Code = Code { id: "ERR-UNPARSEABLE-SQL", level: Level::Error, title: "SQL could not be parsed for static checks", params: &["cause"], template: "Could not parse this SQL: {cause}", fix: Some("First suspect a reserved word used as an alias or CTE name (drop, pivot, share, count): rename it or double-quote it. Then check for an unclosed `(` or a missing comma between CTEs: the parser reports either at the next token, not where it was dropped, and the message leads with the paren count when they differ. PIVOT and UNPIVOT parse in every form DuckDB accepts. If the SQL is valid in your warehouse and still lands here, the construct is one the parser does not model; the error carries the position."), hint: None };
pub const ERR_UNRESOLVED_REFERENCE: Code = Code { id: "ERR-UNRESOLVED-REFERENCE", level: Level::Error, title: "Reference points to an unknown name", params: &["context", "ref"], template: "Reference {ref!r} not found{context}.", fix: None, hint: Some("suggest_layout_chart") };
pub const ERR_URL_VALUE_NOT_ABSOLUTE: Code = Code { id: "ERR-URL-VALUE-NOT-ABSOLUTE", level: Level::Error, title: "a `url` column holds a value that is not an absolute http(s) URL", params: &["value", "where"], template: "{where} is formatted `url`, but row value {value!r} is not an absolute http(s) URL.", fix: None, hint: None };
