pub const ERR_VALUES_ROW_SHAPE: Code = Code { id: "ERR-VALUES-ROW-SHAPE", level: Level::Error, title: "A values row has the wrong number of cells", params: &["query", "row"], template: "query '{query}': values row {row} does not have one cell per column. Rows count from 0; give each row of `values:` exactly one cell per entry of `columns:`.", fix: Some("Give each row of `values:` exactly one cell per entry of `columns:`."), hint: None };
pub const ERR_VARIABLE_COLUMN_INVALID: Code = Code { id: "ERR-VARIABLE-COLUMN-INVALID", level: Level::Error, title: "A variable's column binding names a column that is no SQL identifier", params: &["column", "field_path"], template: "{field_path}: column name {column!r} is not a valid SQL identifier. Use only letters, digits, and underscores.", fix: Some("Write the column half of `table.column` with letters, digits and underscores."), hint: None };
pub const ERR_VARIABLE_CYCLE: Code = Code { id: "ERR-VARIABLE-CYCLE", level: Level::Error, title: "Variables depend on each other in a cycle", params: &["cycle"], template: "Circular variable dependency detected: {cycle}. Variables cannot depend on each other in a cycle. Check the options queries for these variables.", fix: Some("Make the options query of one variable stop reading the other."), hint: None };
pub const ERR_VARIABLE_DEFAULT_INVALID: Code = Code { id: "ERR-VARIABLE-DEFAULT-INVALID", level: Level::Error, title: "A variable default cannot be read as a value", params: &["name", "reason"], template: "Variable {name!r}: {reason}. Give the variable a default that is a literal of its type.", fix: None, hint: None };
pub const ERR_VARIABLE_OPTIONS_FAILED: Code = Code { id: "ERR-VARIABLE-OPTIONS-FAILED", level: Level::Error, title: "Variable options query failed", params: &["cause", "query_name", "variable"], template: "Variable {variable!r} could not load its options (query {query_name!r}): {cause}", fix: Some("Make the variable's `column:` or `options.query` name a table the board's source can read. A table outside the source's own project or database needs its fully qualified name."), hint: None };
pub const ERR_VARIABLE_TABLE_INVALID: Code = Code { id: "ERR-VARIABLE-TABLE-INVALID", level: Level::Error, title: "A variable's column binding names a table that is no SQL identifier", params: &["field_path", "table"], template: "{field_path}: table name {table!r} is not a valid SQL identifier. Use only letters, digits, and underscores, optionally schema-qualified (e.g. 'gis.fact_sales').", fix: Some("Write the table half of `table.column` with letters, digits and underscores, optionally schema-qualified."), hint: None };
