pub const ERR_VARIABLE_VALUE_NOT_IN_OPTIONS: Code = Code { id: "ERR-VARIABLE-VALUE-NOT-IN-OPTIONS", level: Level::Error, title: "Variable value is not one of the variable's options", params: &["options", "value", "variable"], template: "Variable {variable!r} was set to {value!r}, which is not one of its options. Valid options: {options}.", fix: None, hint: None };
pub const ERR_WAREHOUSE_AUTH: Code = Code { id: "ERR-WAREHOUSE-AUTH", level: Level::Error, title: "Warehouse rejected the credentials", params: &["detail"], template: "Warehouse rejected the credentials: {detail}. Refresh or correct the credentials for this source (for BigQuery, `gcloud auth application-default login`), then run it again. The SQL is not at fault.", fix: None, hint: None };
pub const ERR_WAREHOUSE_BYTES_CAP_EXCEEDED: Code = Code { id: "ERR-WAREHOUSE-BYTES-CAP-EXCEEDED", level: Level::Error, title: "Query would scan more than the source's byte cap", params: &["cap", "required"], template: "BigQuery refused the query before running it: it would scan at least {required}, over this source's {cap} per-query cap (maximum_bytes_billed). Narrow the query, then run it again: filter on a partition or date column, select only the columns you need, or aggregate. LIMIT does not reduce bytes scanned.", fix: None, hint: None };
pub const ERR_WAREHOUSE_CONNECTION: Code = Code { id: "ERR-WAREHOUSE-CONNECTION", level: Level::Error, title: "Could not open the warehouse", params: &["origin", "reason", "source"], template: "Could not open the warehouse for source {source!r} ({origin}): {reason} Run `dct doctor --with-warehouse` to test each connection.", fix: Some("Check the source's credentials, host, and network reachability in `dbt_charts.yml` or `profiles.yml`; for a database file, check that it exists and no other process holds its lock."), hint: None };
pub const ERR_WAREHOUSE_PERMISSION: Code = Code { id: "ERR-WAREHOUSE-PERMISSION", level: Level::Error, title: "Warehouse denied access to a relation", params: &["detail", "source"], template: "Warehouse denied access for source {source!r}: {detail}. The credentials were accepted and the SQL was read; the role or account behind them lacks permission on a relation the query uses. Grant that access, or switch the source to a role or credentials that have it, then run it again. The SQL is not at fault.", fix: None, hint: None };
