pub const ERR_WAREHOUSE_RESULT_WARNING: Code = Code { id: "ERR-WAREHOUSE-RESULT-WARNING", level: Level::Error, title: "The warehouse reported a warning about this result", params: &["warnings"], template: "The warehouse reported a warning about this result: {warnings}", fix: Some("Change the query so the warning no longer applies, for example by selecting fewer rows."), hint: None };
pub const ERR_WAREHOUSE_RUNTIME: Code = Code { id: "ERR-WAREHOUSE-RUNTIME", level: Level::Error, title: "Warehouse rejected the query at runtime", params: &["detail"], template: "Warehouse rejected the query: {detail}. Change the SQL to address what that message names, then run it again.", fix: None, hint: None };
pub const ERR_WIDE_MEASURE_NAME_CONTAINS_SEPARATOR: Code = Code { id: "ERR-WIDE-MEASURE-NAME-CONTAINS-SEPARATOR", level: Level::Error, title: "Wide measure name contains the dimension composite separator", params: &["measure", "separator"], template: "Chart authors y: [...] with color: as a dimension, and measure column {measure!r} contains the {separator!r} composite separator, so the composite series name cannot be split back into a dimension value and a measure. Rename the measure column, or alias it in the query.", fix: None, hint: None };
pub const ERR_WRONG_SHAPE: Code = Code { id: "ERR-WRONG-SHAPE", level: Level::Error, title: "Field expects a mapping but got a scalar", params: &["available_keys", "field_path"], template: "Field {field_path!r} expects a mapping, not a scalar. Provide a YAML block with keys: {available_keys}.", fix: None, hint: None };
pub const ERR_X_VALUE_NOT_A_DATE: Code = Code { id: "ERR-X-VALUE-NOT-A-DATE", level: Level::Error, title: "A time-axis x value is not a date", params: &["chart_id", "value", "x_field"], template: "Chart {chart_id!r} plots x field {x_field!r} on a time axis, but {value!r} is not a date or timestamp. Every x value must parse as one; fix the query, or set `axis_x.type: ordinal` to draw the values as categories.", fix: None, hint: None };
pub const ERR_YAML_SYNTAX: Code = Code { id: "ERR-YAML-SYNTAX", level: Level::Error, title: "YAML syntax error", params: &["problem", "quoted_line", "source", "where"], template: "Invalid YAML syntax in {source}{where}: {problem}{quoted_line}", fix: Some("Fix the line quoted above. The usual cause is a string that contains a colon followed by a space, or starts with a special character (`*`, `&`, `!`, `%`, `@`, `[`, `{`): wrap the whole value in quotes, for example `title: \"Ten largest occupations in 1950: rank and workers\"`."), hint: None };
pub const WARN_ADJACENT_TEXT_ROWS: Code = Code { id: "WARN-ADJACENT-TEXT-ROWS", level: Level::Warning, title: "Consecutive text-only rows each flow into their own columns", params: &["count"], template: "{count} text-only rows in a row: each is measured and flowed on its own, so the column grid restarts at every one; the column edges do not line up, and whichever block half-fills its last column leaves a gap mid-page.", fix: Some("Merge them into one `- text:` block. Prose in a single block flows through one set of columns and fills them evenly; the headings that separated the rows still separate the sections inside it."), hint: None };
pub const WARN_ANNOTATION_NOTE_MOVED: Code = Code { id: "WARN-ANNOTATION-NOTE-MOVED", level: Level::Warning, title: "Annotation note moved away from its point", params: &["chart_id", "index"], template: "Chart {chart_id!r}: annotation {index}'s text moved to another side of its point to clear the chart, with no connector back to it.", fix: Some("Set `connector: line` so the note points at its anchor, or set `style.marks.text.position.edge` to keep the text on one side."), hint: None };
pub const WARN_ANNOTATION_NOTHING_DRAWN: Code = Code { id: "WARN-ANNOTATION-NOTHING-DRAWN", level: Level::Warning, title: "Annotation draws nothing", params: &["chart_id", "index", "reason"], template: "Chart {chart_id!r}: annotation {index} draws nothing: {reason}.", fix: Some("Anchor the annotation inside the plotted domain, name a category the chart shows, scope it to rows the chart plots, give a trend enough rows for its fit, or remove it."), hint: None };
pub const WARN_AREA_UNSTACKED_READS_AS_STACKED: Code = Code { id: "WARN-AREA-UNSTACKED-READS-AS-STACKED", level: Level::Warning, title: "Unstacked area is hard to tell apart from a stacked one", params: &["chart_id", "count", "field"], template: "Chart {chart_id!r}: hard to tell this area chart apart from a stacked one. Its {count} series from {field!r} overlap, so the outer edge represents an individual series value, not the total.", fix: Some("Set `style.stack: \"zero\"` if the series compose a total, or use `type: line` if they are independent trends. Which one this occurrence recommends leading with depends on how much of the real total the chart's outer edge is hiding."), hint: None };
pub const WARN_AREA_ZERO_BASELINE_CROPPED: Code = Code { id: "WARN-AREA-ZERO-BASELINE-CROPPED", level: Level::Warning, title: "An area chart's zero baseline is cropped", params: &["chart_id"], template: "Chart {chart_id!r} sets axis_y.scale.continuous.zero to false, so the area's fill starts above zero and overstates the change.", fix: Some("Remove axis_y.scale.continuous.zero to keep the zero baseline, or use `type: line` to zoom into a range. If the crop is deliberate, add WARN-AREA-ZERO-BASELINE-CROPPED to the chart's warnings_ignore."), hint: None };
pub const WARN_AXIS_ALIGN_DISCARDED: Code = Code { id: "WARN-AXIS-ALIGN-DISCARDED", level: Level::Warning, title: "Authored axis_y.labels.align has no effect on a house-format quantitative axis", params: &["authored_align", "chart_id", "format_alias"], template: "Chart {chart_id!r}: axis_y.labels.align = {authored_align!r} has no effect: the format alias {format_alias!r} forces label.align = 'right' on right-edge quantitative axes for correct digit alignment.", fix: Some("Remove axis_y.labels.align from this chart. To opt out of forced alignment, use a literal d3 format spec (e.g. '.1%') instead of the alias."), hint: None };
pub const WARN_AXIS_LABEL_COLLISION: Code = Code { id: "WARN-AXIS-LABEL-COLLISION", level: Level::Warning, title: "X-axis tick labels overlap with no room left to fix it", params: &["chart_id", "field", "label_count"], template: "Chart {chart_id!r}: x field {field!r} has {label_count} tick labels that overlap even after skipping and tilting labels — they will render on top of each other.", fix: Some("Widen the chart, reduce the number of x categories (roll up to a coarser time grain, filter the data), or shorten the labels."), hint: None };
pub const WARN_AXIS_TITLE_TRUNCATED: Code = Code { id: "WARN-AXIS-TITLE-TRUNCATED", level: Level::Warning, title: "Axis title was too long and was truncated with an ellipsis", params: &["authored_field", "authored_text", "chart_id"], template: "Chart {chart_id!r}: {authored_field!r} was truncated: the authored text {authored_text!r} did not fit within two lines at the available extent.", fix: Some("Shorten the axis title, or widen the chart so the title has more room."), hint: None };
pub const WARN_BAR_BAND_WIDTH_TOO_NARROW: Code = Code { id: "WARN-BAR-BAND-WIDTH-TOO-NARROW", level: Level::Warning, title: "Bar chart bands are too narrow to read", params: &["bar_width", "chart_id", "distinct", "min_band_width", "render_width", "series"], template: "Chart {chart_id!r} has {distinct} bands x {series} series across {render_width:.0f}px (~{bar_width:.2f}px per bar); {min_band_width:.0f}px is the threshold this configuration crosses, so bars will read as a merged block instead of separate marks.", fix: Some("Widen the chart (or, for a horizontal bar, make it taller), reduce the number of categories, or (for time series) roll up to a coarser grain (e.g. day -> week or month)."), hint: None };
pub const WARN_BAR_CATEGORY_TICKS: Code = Code { id: "WARN-BAR-CATEGORY-TICKS", level: Level::Warning, title: "Bar category axis draws a tick under every bar", params: &[], template: "axis_x.ticks.visible is on, so a tick sits under every bar and repeats what the bars already mark. Set axis_x.ticks.visible: false to turn the ticks off.", fix: Some("Set `axis_x.ticks.visible: false` in the chart's style."), hint: None };
pub const WARN_BAR_GROUPED_SERIES_COINCIDE: Code = Code { id: "WARN-BAR-GROUPED-SERIES-COINCIDE", level: Level::Warning, title: "Grouped bar series paint on top of each other", params: &["chart_id", "field"], template: "Chart {chart_id!r}: {field!r} is a temporal axis with no calendar grain to bucket by, so its color-grouped bars have no band to offset series within: every series paints at the same position, hiding all but the last one drawn.", fix: Some("Switch the x field to a categorical or bucketed-time column (so bars group side by side), or use a line/area/scatter mark, which already draw overlapping series legibly on a continuous time axis."), hint: None };
pub const WARN_BODY_HEADING_NO_TITLE: Code = Code { id: "WARN-BODY-HEADING-NO-TITLE", level: Level::Warning, title: "Text opens with a heading but the board has no title", params: &["heading"], template: "Text opens with the markdown heading {heading!r} and this board has no `title:`, so the heading renders as prose rather than a section title.", fix: Some("Set `title: {heading}` and delete the heading line from the text; section titles belong on the board, not in the markdown. If this text isn't a new section, it shouldn't be its own row: merge it into the text before it."), hint: None };
pub const WARN_CALLOUT_TEXT_TRUNCATED: Code = Code { id: "WARN-CALLOUT-TEXT-TRUNCATED", level: Level::Warning, title: "Callout text was truncated", params: &["authored_field", "authored_text", "chart_id"], template: "Chart {chart_id!r}: callout {authored_field!r} was truncated: the authored text {authored_text!r} exceeded the maximum lines.", fix: Some("Shorten the callout text, or increase the chart height/width."), hint: None };
pub const WARN_CATEGORY_COLOR_PIN_UNSEEN: Code = Code { id: "WARN-CATEGORY-COLOR-PIN-UNSEEN", level: Level::Warning, title: "A category_colors pin names a value this render never draws", params: &["drawn", "field", "values"], template: "`style.charts.category_colors.{field}` pins {values}, which this render does not draw; the pin was skipped. This render draws {drawn} for `{field}`.", fix: Some("Write the pin exactly as one of the drawn values is spelled, or remove the pin if no chart draws that value. A narrowed `--chart` layout can also leave a pinned value undrawn."), hint: None };
pub const WARN_CHART_TITLE_TRUNCATED: Code = Code { id: "WARN-CHART-TITLE-TRUNCATED", level: Level::Warning, title: "Chart title or subtitle was truncated with an ellipsis", params: &["authored_field", "authored_text", "chart_id"], template: "Chart {chart_id!r}: {authored_field!r} was truncated: the authored text {authored_text!r} did not fit within the available width.", fix: Some("Shorten the title or subtitle, or widen the chart: a board without an authored `width:` hugs its charts, so set the board's `width:` or the chart's `width:`."), hint: None };
pub const WARN_COLUMN_CHECK_UNAVAILABLE: Code = Code { id: "WARN-COLUMN-CHECK-UNAVAILABLE", level: Level::Warning, title: "Column check unavailable on this adapter", params: &["adapter_type", "mechanism"], template: "Column check unavailable on {adapter_type} ({mechanism} validates the query but returns no result schema).", fix: Some("Chart column checks need a schema-bearing mechanism (DuckDB, BigQuery dry run). Verify chart columns against a sample run, e.g. dct query <board> <name>."), hint: None };
pub const WARN_DATE_AS_TEXT: Code = Code { id: "WARN-DATE-AS-TEXT", level: Level::Warning, title: "A charted x column is a date the query turned into text", params: &["message", "query_name"], template: "Query {query_name!r}: {message}", fix: Some("Return the date itself (with date_trunc for a grain) instead of formatting it; the axis labels dates by grain. For a month-of-year or day-of-week category, return the month or weekday name."), hint: None };
pub const WARN_DBT_MANIFEST_MISSING: Code = Code { id: "WARN-DBT-MANIFEST-MISSING", level: Level::Warning, title: "Queries use dbt macros but no manifest was found", params: &["kind", "paths"], template: "Queries use {kind} but no dbt manifest was found (looked for {paths}); refs were not validated.", fix: Some("Run 'dbt parse' in the dbt project."), hint: None };
pub const WARN_DBT_MODEL_COLUMNS_UNRESOLVED: Code = Code { id: "WARN-DBT-MODEL-COLUMNS-UNRESOLVED", level: Level::Warning, title: "A dbt model's output columns could not be derived statically", params: &["model", "query_name", "reason"], template: "Query {query_name!r} reads dbt model {model!r}, whose output columns could not be derived from its SQL ({reason}); column references against it were not checked.", fix: Some("The reason names what blocks static derivation (a `SELECT *` wants explicit projections; an unaliased cast or expression wants an alias; seeds and snapshots are never derivable); the columns can always be verified with `dct validate --warehouse` after `dbt run`."), hint: None };
pub const WARN_DBT_QUERY_COLUMNS_INDETERMINATE: Code = Code { id: "WARN-DBT-QUERY-COLUMNS-INDETERMINATE", level: Level::Warning, title: "A query's dbt column references could not be determined", params: &["query_name", "reason"], template: "Query {query_name!r} uses dbt ref()/source() but the columns it reads could not be determined ({reason}); they were not checked against the dbt models.", fix: Some("The reason names what blocks the analysis (a `SELECT *` wants explicit columns; a templated identifier is decided at render time); the query can always be verified with `dct validate --warehouse` after `dbt run`."), hint: None };
pub const WARN_DEFAULTS_FILE_GIVEN_AS_BOARD: Code = Code { id: "WARN-DEFAULTS-FILE-GIVEN-AS-BOARD", level: Level::Warning, title: "A defaults file was given to dct render", params: &["path"], template: "{path} holds defaults for the boards beside it; skipped.", fix: Some("Nothing to fix when a glob picked it up. To see its effect, render a board in the same directory."), hint: None };
pub const WARN_DOUBLE_HEADER: Code = Code { id: "WARN-DOUBLE-HEADER", level: Level::Warning, title: "Board title is repeated by a heading at the top of the body", params: &["heading", "level", "title"], template: "Board title {title!r} is followed immediately by a level-{level} markdown heading {heading!r}; the board renders both, so the dashboard headers itself twice.", fix: Some("Delete the heading line from the body; `title:` already renders as the board header. If you would rather keep the heading, drop `title:` instead and let it be the header."), hint: None };
pub const WARN_DUAL_AXIS_COMPETING_SCALES: Code = Code { id: "WARN-DUAL-AXIS-COMPETING-SCALES", level: Level::Warning, title: "Dual-axis chart plots two measures on independent scales", params: &["base_col", "chart_id", "layer_col"], template: "Chart {chart_id!r}: {layer_col!r} is drawn against its own y-axis, separate from {base_col}. The two scales are set independently, so where the marks cross, which one sits higher, and how closely they track are artifacts of the axis ranges, not the data: readers will see a relationship that may not exist.", fix: Some("Show each measure in its own chart, stacked so they share the x-axis. To compare trends in one chart, index both series to a common start (e.g. 100) in the query so they share one axis; to show how one measure moves with the other, plot them as a scatter. If the second series is the same quantity in another unit (°F/°C, $/€), remove the layer and relabel the chart's opposite edge with `style.axis_y.mirror` and an `expr` that converts the value (for example `format(datum.value * 1.8 + 32, '.0f')`): one scale, two unit labels. Where the audience expects this form, list the code in the chart's `warnings_ignore:`. Both scales draw full-width gridlines, which interleave into an uneven ladder; set `axis_y.grid.visible: false` on the pinned layer to keep one set."), hint: None };
pub const WARN_ENDPOINT_LABEL_GAP_OVERFLOW: Code = Code { id: "WARN-ENDPOINT-LABEL-GAP-OVERFLOW", level: Level::Warning, title: "Endpoint-label rail is too cramped for its intended spacing", params: &["chart_id", "gap_px", "series_count"], template: "Chart {chart_id!r} packs {series_count} endpoint labels needing {gap_px:.0f}px apart into a plot shorter than that: labels are distributed evenly across the plot instead of at their intended spacing.", fix: Some("Give the chart more height, reduce the number of series, or switch to a color legend instead of an endpoint-label rail."), hint: None };
pub const WARN_ENDPOINT_LABEL_RAIL_OVERFLOW: Code = Code { id: "WARN-ENDPOINT-LABEL-RAIL-OVERFLOW", level: Level::Warning, title: "Endpoint-label rail dropped series that had no room, despite fitting overall", params: &["chart_id", "dropped_count", "gap_px", "series_count"], template: "Chart {chart_id!r}: {dropped_count} of {series_count} endpoint labels could not be placed {gap_px:.0f}px apart and were dropped from the rail rather than piled onto the same spot.", fix: Some("Unlike a rail that is cramped everywhere, more height reliably helps here: it gives the clustered anchors room to spread apart from whichever series they crowded against. Reducing the series count or switching to a color legend also works."), hint: None };
pub const WARN_ENDPOINT_LABEL_RAIL_TIED: Code = Code { id: "WARN-ENDPOINT-LABEL-RAIL-TIED", level: Level::Warning, title: "Endpoint-label rail has no spread to place labels along", params: &["chart_id", "series_count"], template: "Chart {chart_id!r}: all {series_count} series end on the same value, so the rail has no vertical spread to space labels by: they are distributed evenly across the plot instead of stacking on one point.", fix: Some("This is a property of the data, not the layout; more height will not change it. Check whether the trailing rows are null or zero for every series; if that is expected, a color legend names the series without implying distinct endpoints."), hint: None };
pub const WARN_FACET_PANEL_WIDTH_BELOW_MINIMUM: Code = Code { id: "WARN-FACET-PANEL-WIDTH-BELOW-MINIMUM", level: Level::Warning, title: "Small-multiples panel width shrank below the legibility floor", params: &["chart_id", "min_panel_px", "panel_cols", "panel_width"], template: "Chart {chart_id!r} facets into {panel_cols} column panel(s) at {panel_width:.0f}px each, below the {min_panel_px:.0f}px floor small multiples need to stay legible.", fix: Some("Widen the chart, reduce the column-facet's cardinality, or move part of the split from `multiples.columns` to `multiples.rows` (rows stack vertically instead of dividing the card's width)."), hint: None };
pub const WARN_FLAT_COLS_UNSIZED_OVERFLOW: Code = Code { id: "WARN-FLAT-COLS-UNSIZED-OVERFLOW", level: Level::Warning, title: "Flat cols: row has too many unsized non-KPI cells", params: &["growable_count", "max_unsized"], template: "cols: has {growable_count} unsized non-KPI cells (max recommended {max_unsized}). Each inherits the row's full vertical budget, so a wide flat row makes row height unpredictable. KPI cards are height-stable and don't count.", fix: Some("Nest cells into sized rows-in-cols groups instead, e.g.:\n  cols:\n  - width: \"17%\"\n    rows:\n      - kpi_a\n      - kpi_b\n  - width: \"55%\"\n    rows:\n      - hero"), hint: None };
pub const WARN_FORMAT_UNUSED_NAME: Code = Code { id: "WARN-FORMAT-UNUSED-NAME", level: Level::Warning, title: "style.formats name is defined but nothing uses it", params: &["did_you_mean", "name"], template: "`style.formats.{name}` is defined but nothing uses it.{did_you_mean} To restyle an engine format, redefine its name (`number`, `currency`, `date_short`, ...).", fix: Some("Name it in a `format:` slot, redefine an engine name instead, or delete it."), hint: None };
pub const WARN_GRADIENT_HINGE_MISMATCH: Code = Code { id: "WARN-GRADIENT-HINGE-MISMATCH", level: Level::Warning, title: "Color scale hinge does not match its palette or data", params: &["chart_id", "field", "problem"], template: "Chart {chart_id!r}: the color scale on {field!r} {problem}.", fix: Some("Set `hinge` to the value that should read as neutral (0 for signed data) on a diverging palette, and omit `hinge` on a sequential one."), hint: None };
pub const WARN_HEADING_MARGIN_REDEFINED: Code = Code { id: "WARN-HEADING-MARGIN-REDEFINED", level: Level::Warning, title: "Authored heading margin now sizes fewer headings", params: &["key", "meaning"], template: "`style.text.heading.{key}` no longer sets the space around every heading: {meaning}", fix: Some("Delete the key to take the theme's spacing, or keep it for the levels it still sizes. `style.text.paragraph` sets the gap the other levels take."), hint: None };
pub const WARN_HEADING_TRAILING_PERIOD: Code = Code { id: "WARN-HEADING-TRAILING-PERIOD", level: Level::Warning, title: "Heading ends with a period", params: &["text"], template: "Title {text!r} ends with a period; headings do not take one.", fix: Some("Delete the trailing period from the title."), hint: None };
pub const WARN_HTML_POLICY_CAPPED: Code = Code { id: "WARN-HTML-POLICY-CAPPED", level: Level::Warning, title: "Board html_policy downgraded by deployment ceiling", params: &["ceiling", "ceiling_source", "effective", "requested"], template: "Board requested html_policy={requested!r} but the {ceiling_source} ceiling is {ceiling!r}; effective policy is {effective!r}. Raw HTML in this board will be treated as {effective!r}.", fix: Some("Either lower the board's `html_policy:` to {effective!r} to match what is actually rendered, or raise the deployment ceiling (DCT_HTML_POLICY_CEILING or html_policy_ceiling in dbt_charts.yml) if the deployment operator permits it."), hint: None };
pub const WARN_INHERITED_LAYOUT_REPLACED: Code = Code { id: "WARN-INHERITED-LAYOUT-REPLACED", level: Level::Warning, title: "A board's own layout or tags replace the inherited ones", params: &["field", "inherited", "replacer", "source"], template: "`{field}:` {replacer} replaces {inherited} inherited from {source}.", fix: Some("To keep the inherited items, move the shared parts into a partial and import it from both boards."), hint: None };
pub const WARN_KPI_ALIGN_OVERFLOW: Code = Code { id: "WARN-KPI-ALIGN-OVERFLOW", level: Level::Warning, title: "KPI align was ignored because a text run overflowed the card", params: &["chart_id"], template: "Chart {chart_id!r}: a text run is wider than the card, so align: center/right was not applied; every run on the card stays left-aligned and the overflowing one spills past the right edge.", fix: Some("Widen the card, shorten the value with a more compact format, or drop align: so the left-aligned overflow is expected."), hint: None };
pub const WARN_KPI_INLINE_VARIANT_FALLBACK_TO_STACKED: Code = Code { id: "WARN-KPI-INLINE-VARIANT-FALLBACK-TO-STACKED", level: Level::Warning, title: "KPI inline variant fell back to stacked", params: &["authored_text", "chart_id"], template: "Chart {chart_id!r}: style.variant: {authored_text!r} did not fit the card at the available width: value, label, and support fell back to the stacked arrangement instead of painting past the card edge.", fix: Some("Widen the card, shorten the label or support text, or author style.variant: stacked directly."), hint: None };
pub const WARN_KPI_LABEL_TRUNCATED: Code = Code { id: "WARN-KPI-LABEL-TRUNCATED", level: Level::Warning, title: "KPI card label was truncated", params: &["authored_text", "chart_id"], template: "Chart {chart_id!r}: KPI label was truncated: the authored text {authored_text!r} did not fit within the card at the available width.", fix: Some("Shorten the KPI label, widen the card, or use a smaller font size."), hint: None };
pub const WARN_KPI_SUPPORT_TRUNCATED: Code = Code { id: "WARN-KPI-SUPPORT-TRUNCATED", level: Level::Warning, title: "KPI card support line was truncated", params: &["authored_text", "chart_id"], template: "Chart {chart_id!r}: KPI support line was truncated: the authored text {authored_text!r} did not fit within the card at the available width.", fix: Some("Shorten the support label, widen the card, or use a smaller font size."), hint: None };
pub const WARN_LABEL_TITLE_CASE: Code = Code { id: "WARN-LABEL-TITLE-CASE", level: Level::Warning, title: "Authored label is in Title Case", params: &["text"], template: "{text!r} capitalizes its words like a heading; labels print as written, so it will show in Title Case.", fix: Some("Write the label in sentence case, keeping proper nouns and acronyms capitalized. Leave it as is if the capitals are proper nouns."), hint: None };
pub const WARN_LAYER_DATA_OUTSIDE_DOMAIN: Code = Code { id: "WARN-LAYER-DATA-OUTSIDE-DOMAIN", level: Level::Warning, title: "Layer data falls outside its authored y domain", params: &["chart_id", "data_max", "data_min", "hi", "layer_col", "lo"], template: "Chart {chart_id!r}: layer {layer_col!r} has values from {data_min} to {data_max}, but its `axis_y.scale.domain` is [{lo}, {hi}], so the marks outside the domain are cut off at the plot edge.", fix: Some("Widen `axis_y.scale.domain` to cover the data, or filter the rows in the query. To let the marks run past the plot deliberately, set `axis_y.scale.clip: false` on the layer."), hint: None };
pub const WARN_LAYER_X_DOMAIN_PAINT_ORDER: Code = Code { id: "WARN-LAYER-X-DOMAIN-PAINT-ORDER", level: Level::Warning, title: "Layered chart x-axis is ordered by paint order, not by the data", params: &["chart_id", "n_new", "plural", "sample", "x_field"], template: "Chart {chart_id!r}: layer queries contribute {n_new} x categor{plural} ({sample}) that the base query never returns on {x_field!r}, and there is no order the base states to place them into, so the axis is drawn base-query rows first, then each layer's, and the left-to-right reading order is paint order rather than an ordering the data states.", fix: Some("Return every x category from one query: join the layers onto a shared spine so the axis order is that query's. An authored `sort:` is not a fix: it orders only the categories the base query returns and leaves the layer's appended in paint order."), hint: None };
pub const WARN_LAYERED_CHART_SHARED_Y_AXIS_SCALE_MISMATCH: Code = Code { id: "WARN-LAYERED-CHART-SHARED-Y-AXIS-SCALE-MISMATCH", level: Level::Warning, title: "Layered chart y series have a large scale mismatch", params: &["chart_id", "col_a", "col_b", "reach"], template: "Chart {chart_id!r}: y columns {col_a!r} and {col_b!r} share a y-axis, and {col_b!r} reaches only {reach:.1%} of it: the smaller series will be visually crushed to a flat line.", fix: Some("Index the series to a common scale in the query (e.g. percent change, or 100 = first period), or show them as two charts stacked so they share the x-axis."), hint: None };
pub const WARN_LAYOUT_MIN_EXCEEDS_HEIGHT: Code = Code { id: "WARN-LAYOUT-MIN-EXCEEDS-HEIGHT", level: Level::Warning, title: "Chart's category count needs more height than its row allows", params: &["authored_height", "chart_id", "min_height", "n_categories"], template: "Chart {chart_id!r} has {n_categories} category bands, which need at least {min_height:.0f}px to stay readable, but its row/tile height caps it at {authored_height:.0f}px. The chart rendered at {min_height:.0f}px anyway: the row's authored height was not honored, and any sibling charts sharing the row grew to match.", fix: Some("Raise the row's height to fit the category count, or reduce the categories (filter, paginate, or roll up to a coarser grain) so the readable minimum fits inside the authored height."), hint: None };
pub const WARN_LEGEND_HIDDEN_UNDER_EDGE: Code = Code { id: "WARN-LEGEND-HIDDEN-UNDER-EDGE", level: Level::Warning, title: "A hidden legend under a legend edge names no series", params: &["chart_id", "edge"], template: "Chart {chart_id!r} hides its legend, but `legend.position.edge: {edge}` also keeps endpoint labels off, so nothing names its series.", fix: Some("Set `legend.position.edge: endpoints` to name the series on the chart, or set `legend.visible: true` to show the legend."), hint: None };
pub const WARN_LEGEND_OVERLAY_COVERS_MARKS: Code = Code { id: "WARN-LEGEND-OVERLAY-COVERS-MARKS", level: Level::Warning, title: "An overlay legend covers data marks", params: &["chart_id"], template: "Chart {chart_id!r}: the overlay legend sits on top of the data, hiding part of a mark.", fix: Some("Move the legend to a corner the data leaves empty (`legend.position`), or set `overlay` to false to reserve a strip for it."), hint: None };
pub const WARN_LEGEND_POSITION_WIDTH_FALLBACK: Code = Code { id: "WARN-LEGEND-POSITION-WIDTH-FALLBACK", level: Level::Warning, title: "A narrow card overrode an authored legend edge", params: &["authored_edge", "chart_id", "resolved_edge"], template: "Chart {chart_id!r} authored `legend.position.edge: {authored_edge}`, but a card this narrow cannot hold that placement, so the legend was placed on the `{resolved_edge}` edge instead.", fix: Some("Widen the chart, or drop `legend.position.edge` and accept the automatic placement."), hint: None };
pub const WARN_LEGEND_VALUES_UNRESOLVED: Code = Code { id: "WARN-LEGEND-VALUES-UNRESOLVED", level: Level::Warning, title: "style.legend.values entry does not resolve against the legend domain", params: &["chart_id", "domain", "values"], template: "Chart {chart_id!r} authored `legend.values` entries {values} that did not resolve to exactly one legend entry. Legend domain: {domain}.", fix: Some("Check the spelling against the legend domain, or remove the entry if it's expected to be legitimately absent sometimes."), hint: None };
pub const WARN_LINE_JOINS_MISSING_PERIODS: Code = Code { id: "WARN-LINE-JOINS-MISSING-PERIODS", level: Level::Warning, title: "Line joins straight across periods missing from the data", params: &["by_series", "chart_id", "chart_type", "detail", "first", "grain", "last", "y_field"], template: "Chart {chart_id!r}: the {chart_type} joins straight across periods that have no row, so the gap reads as data: {detail}.", fix: Some("Make each missing period a row with a NULL `{y_field}`: LEFT JOIN the query to a spine of every {grain} from {first} to {last} (`generate_series` or a date table){by_series}. The line then breaks at the gap. If the join is deliberate, add `warnings_ignore: [WARN-LINE-JOINS-MISSING-PERIODS]` to chart {chart_id!r}."), hint: None };
pub const WARN_LINK_TARGET_NOT_FOUND: Code = Code { id: "WARN-LINK-TARGET-NOT-FOUND", level: Level::Warning, title: "A board link names a board that does not exist", params: &["field_path", "link", "slug"], template: "Link {link!r} at {field_path} points at {slug!r}, which is not a board in this project.", fix: Some("Write the slug of an existing board as a root-relative path, such as '/user-360'."), hint: None };
pub const WARN_LOCAL_TIME_LABEL_EXPR_ON_BUCKETED_AXIS: Code = Code { id: "WARN-LOCAL-TIME-LABEL-EXPR-ON-BUCKETED-AXIS", level: Level::Warning, title: "Authored axis label expression uses local time on a bucketed axis", params: &["accessor", "chart_id", "time_unit"], template: "Chart {chart_id!r}: axis_x.labels.expr calls {accessor}(), which reads datum.value in the render process's time zone. Static rendering pins that to UTC, so the {time_unit!r} bucketing's UTC-midnight tick values resolve in UTC today, not necessarily the zone you or the chart's viewers are actually in, and dbt charts has no way to render this in a different zone.", fix: Some("Replace local-time accessors with their utc-prefixed equivalents (utcFormat()/utcyear()/utcmonth()/...), e.g. utcFormat(toDate(datum.value), '%b %Y'), to make the UTC result explicit instead of implying a local-time read that never happens."), hint: None };
pub const WARN_LOW_TEXT_CONTRAST: Code = Code { id: "WARN-LOW-TEXT-CONTRAST", level: Level::Warning, title: "Text ink has too little contrast against its background", params: &["background", "element", "floor", "ink", "key", "ratio", "size"], template: "{element} is painted {ink} on {background} -- {ratio:.1f}:1 contrast, below the {floor:.1f}:1 floor for {size} text.", fix: Some("Set {key} to a color with more contrast against {background}."), hint: None };
pub const WARN_MISSING_JOIN_PREDICATE: Code = Code { id: "WARN-MISSING-JOIN-PREDICATE", level: Level::Warning, title: "Join is missing a predicate and may produce a cross join", params: &["message", "query_name"], template: "Query {query_name!r}: {message}", fix: Some("Add an ON clause that relates the tables, or join a source that returns one row (an aggregate with no GROUP BY, or LIMIT 1). Intentional? Silence it with `ignore: [WARN-MISSING-JOIN-PREDICATE]` on the query."), hint: None };
pub const WARN_NORMALIZE_PERCENT_FORMAT_READS_RAW_VALUE: Code = Code { id: "WARN-NORMALIZE-PERCENT-FORMAT-READS-RAW-VALUE", level: Level::Warning, title: "Percent format on a 100% stack formats the raw value, not the share", params: &["chart_id", "field", "format", "total"], template: "Chart {chart_id!r}: percent format {format!r} formats the raw {field!r} value, not the share the normalized stack paints: one stack group's values sum to {total}, not 1, so the hover rows and the value labels multiply a raw number by 100 and print it as a percentage.", fix: Some("Drop the percent format (a normalized stack already labels its axis 0-100%, so the format never reaches that axis), or make the measure a real 0..1 share in SQL by dividing each value by its group's total, so the raw value and the painted share are the same number."), hint: None };
pub const WARN_PALETTE_UNSUPPORTED: Code = Code { id: "WARN-PALETTE-UNSUPPORTED", level: Level::Warning, title: "Palette name is a known anti-pattern", params: &["chart_id", "requested", "resolved"], template: "Chart {chart_id!r}: palette {requested!r} is a known anti-pattern; resolved to {resolved} instead.", fix: Some("Author a supported palette name; the substitute named in the message is what renders."), hint: None };
pub const WARN_PARSE_ERROR: Code = Code { id: "WARN-PARSE-ERROR", level: Level::Warning, title: "SQL query could not be parsed for semantic validation", params: &["message", "query_name"], template: "Query {query_name!r}: {message}", fix: Some("Check the SQL syntax. The query may still execute, but semantic validation (reaggregation, missing join predicates) cannot run on unparseable SQL."), hint: None };
pub const WARN_PATTERN_FALLBACK_FLAT: Code = Code { id: "WARN-PATTERN-FALLBACK-FLAT", level: Level::Warning, title: "Marks too small for their pattern draw a flat tint", params: &["chart_id", "count"], template: "Chart {chart_id!r}: {count} mark(s) are too small to show their pattern and draw a flat tint instead.", fix: Some("Give the chart wider marks (more width, fewer bars or points) so each pattern repeats at least 1.25 times across the mark."), hint: None };
pub const WARN_PIE_DOMINANT_SEGMENT: Code = Code { id: "WARN-PIE-DOMINANT-SEGMENT", level: Level::Warning, title: "Pie chart is dominated by a single segment", params: &["chart_id", "dominant_field", "dominant_share"], template: "Pie chart {chart_id!r}: {dominant_field!r} holds {dominant_share:.0%} of the total; the chart conveys a single value.", fix: Some("Use a KPI chart for the dominant share and a bar or table for the breakdown, rather than a pie dominated by one slice."), hint: None };
pub const WARN_PIE_SIZED_MODE_MISSES_GUARD: Code = Code { id: "WARN-PIE-SIZED-MODE-MISSES-GUARD", level: Level::Warning, title: "Pie is drawn in a box that its labels crowd", params: &["chart_id", "floor", "mode", "ratio"], template: "Pie chart {chart_id!r} keeps its {mode} labels, but in this box the wheel is only {ratio:.0%} of the size it would have without them (the floor is {floor:.0%}).", fix: Some("Remove the authored height that pins this chart's box, or widen the card, so the pie is laid out in the box its labels were sized for."), hint: None };
pub const WARN_PIE_TOTAL_EXCEEDS_INNER_RADIUS: Code = Code { id: "WARN-PIE-TOTAL-EXCEEDS-INNER-RADIUS", level: Level::Warning, title: "Donut center total is too wide for the hole", params: &["chart_id", "formatted_value", "hole_diameter", "slot_height", "slot_width", "text_width"], template: "Donut chart {chart_id!r}: center total {formatted_value!r} is {text_width:.1f}px wide but the hole is only {hole_diameter:.1f}px across (slot {slot_width:.0f}×{slot_height:.0f}px).", fix: Some("Use a compacting number format (e.g. `format: number`) to shorten the total, or enlarge whichever slot dimension is smaller so the hole diameter increases."), hint: None };
pub const WARN_PLOT_HEIGHT_BELOW_MINIMUM: Code = Code { id: "WARN-PLOT-HEIGHT-BELOW-MINIMUM", level: Level::Warning, title: "Chart chrome squeezes the plot below its readability floor", params: &["card_height", "chart_id", "floor_px", "plot_height"], template: "Chart {chart_id!r} squeezes its plot to an estimated {plot_height:.0f}px on a {card_height:.0f}px card, below the {floor_px:.0f}px floor it needs to stay readable.", fix: Some("Give the chart more height, drop authored chrome that is not earning its space here (subtitle, axis titles, a high-cardinality legend), or accept the smaller size deliberately and suppress this warning per-chart with `warnings_ignore`."), hint: None };
pub const WARN_PLOT_WIDTH_BELOW_MINIMUM: Code = Code { id: "WARN-PLOT-WIDTH-BELOW-MINIMUM", level: Level::Warning, title: "A support_table column block claims most of the card's width", params: &["block_width", "card_width", "chart_id", "plot_width"], template: "Chart {chart_id!r}: the support_table column block ({block_width:.0f}px) already claims most of the {card_width:.0f}px card, leaving the plot an estimated {plot_width:.0f}px.", fix: Some("Drop a support_table column, widen the card, or move the block to `position: right` — or accept it deliberately and suppress this warning per-chart with `warnings_ignore`."), hint: None };
pub const WARN_POINT_MAP_NEGATIVE_SIZE_VALUES: Code = Code { id: "WARN-POINT-MAP-NEGATIVE-SIZE-VALUES", level: Level::Warning, title: "Point map size measure has negative values", params: &["chart_id", "dropped_count", "size_field", "total_count"], template: "Point map {chart_id!r}: {dropped_count} of {total_count} points have a negative {size_field!r} value and were not drawn; mark area cannot be negative.", fix: Some("Size by a magnitude instead of a signed value (e.g. `size: abs({size_field})` in the query) and encode direction with a diverging `color:` instead."), hint: None };
