pub const WARN_QUERY_RESULT_TRUNCATED: Code = Code { id: "WARN-QUERY-RESULT-TRUNCATED", level: Level::Warning, title: "Chart query result truncated", params: &["kept_row_count", "reason", "subject"], template: "{subject}: query result exceeded the {reason} limit; truncated to {kept_row_count} rows.", fix: Some("Add a LIMIT to the query, narrow its filters, or raise execution.max_rows/max_result_bytes in dbt_charts.yml if the full result is genuinely needed."), hint: None };
pub const WARN_QUERY_RETURNED_ZERO_ROWS: Code = Code { id: "WARN-QUERY-RETURNED-ZERO-ROWS", level: Level::Warning, title: "Chart query returned zero rows", params: &["chart_id"], template: "Chart {chart_id!r}: query returned zero rows.", fix: Some("Check the WHERE clause or date filter: it may be excluding all data for the current filter values."), hint: None };
pub const WARN_RAIL_VALUE_DROPPED: Code = Code { id: "WARN-RAIL-VALUE-DROPPED", level: Level::Warning, title: "Endpoint label shows its series name without the value", params: &["authored_field", "chart_id", "count", "labels", "labels_noun", "were"], template: "Chart {chart_id!r}: {count} endpoint {labels_noun} from {authored_field!r} {were} drawn without the final value, because the value and the name fit neither one line nor two in the rail: {labels}.", fix: Some("Shorten the {authored_field} values, widen the chart, or set style.legend.position.edge: top to keep the series names in the legend."), hint: None };
pub const WARN_REAGGREGATION: Code = Code { id: "WARN-REAGGREGATION", level: Level::Warning, title: "Grouping-dependent aggregate applied on top of an aggregated input", params: &["message", "query_name"], template: "Query {query_name!r}: {message}", fix: Some("Compute the aggregate once over the underlying rows, or carry the SUM and COUNT up and divide them in the outer query."), hint: None };
pub const WARN_REDUNDANT_ENCODING: Code = Code { id: "WARN-REDUNDANT-ENCODING", level: Level::Warning, title: "Same column bound to two visual channels", params: &["channels", "chart_id", "field"], template: "Chart {chart_id!r}: field {field!r} is bound to channels {channels}: binding the same field twice adds no information.", fix: Some("Remove one of the channel bindings, or use different fields for each channel to encode distinct dimensions."), hint: None };
pub const WARN_RESTATED_FORMAT: Code = Code { id: "WARN-RESTATED-FORMAT", level: Level::Warning, title: "Authored format equals the query's declared format", params: &["path", "source", "value"], template: "`{path}: {value}` is already {source}; remove it.", fix: Some("Delete `{path}`. Keep a key only to override a different inherited or inferred value."), hint: None };
pub const WARN_RESTATED_INFERRED: Code = Code { id: "WARN-RESTATED-INFERRED", level: Level::Warning, title: "Authored value equals the one the engine infers", params: &["path", "source", "value"], template: "`{path}: {value}` is already {source}; remove it.", fix: Some("Delete `{path}`. Keep a key only to override a different inherited or inferred value."), hint: None };
pub const WARN_RESTATED_STYLE: Code = Code { id: "WARN-RESTATED-STYLE", level: Level::Warning, title: "Authored style equals the value it inherits", params: &["path", "source", "value"], template: "`{path}: {value}` is already {source}; remove it.", fix: Some("Delete `{path}`. Keep a key only to override a different inherited or inferred value."), hint: None };
pub const WARN_RETIRED_IGNORE_CODE: Code = Code { id: "WARN-RETIRED-IGNORE-CODE", level: Level::Warning, title: "Ignore list names a retired warning code", params: &["code", "source"], template: "{source}: {code} no longer exists and suppresses nothing", fix: Some("Remove it from the ignore list."), hint: None };
pub const WARN_SCATTER_STACKED_IN_COLUMNS: Code = Code { id: "WARN-SCATTER-STACKED-IN-COLUMNS", level: Level::Warning, title: "Scatter points stack in columns", params: &["channel", "distinct", "points"], template: "{channel} has {distinct} distinct values across {points} points, so the dots stack in columns. Treat {channel} as a category and use a strip plot or beeswarm to show each group's spread.", fix: Some("Chart the grouping channel as a category and spread each group's points with a strip plot or beeswarm; use a bar if only the group totals matter."), hint: None };
pub const WARN_SCHEMA_MIGRATED: Code = Code { id: "WARN-SCHEMA-MIGRATED", level: Level::Warning, title: "Board YAML uses retired syntax", params: &["message"], template: "{message}", fix: Some("Run `dct migrate` to rewrite the file, or update the YAML by hand where the message says `dct migrate` cannot."), hint: None };
pub const WARN_SEMANTIC_COMPILE_FAILED: Code = Code { id: "WARN-SEMANTIC-COMPILE-FAILED", level: Level::Warning, title: "Semantic SQL could not be compiled", params: &["message", "query_name"], template: "Query {query_name!r}: {message}", fix: Some("Use the names `dct semantics SOURCE` lists: a dataset or constellation as the table, AGG(calculation) or AGG(metric) for measures, and relationship.attribute paths or roles to group by."), hint: None };
pub const WARN_SERIES_LABEL_TRUNCATED: Code = Code { id: "WARN-SERIES-LABEL-TRUNCATED", level: Level::Warning, title: "Series label was too long for the endpoint-label rail and was truncated", params: &["authored_field", "chart_id", "count", "labels", "labels_noun", "were"], template: "Chart {chart_id!r}: {count} series {labels_noun} from {authored_field!r} {were} truncated in the endpoint-label rail, which is capped at a fraction of the chart's width: {labels}.", fix: Some("Shorten the {authored_field} values, widen the chart, or set style.legend.position.edge: top to keep the series names in the legend."), hint: None };
pub const WARN_SERIES_LABELS_REPEAT_WORD: Code = Code { id: "WARN-SERIES-LABELS-REPEAT-WORD", level: Level::Warning, title: "Every series label repeats the same word", params: &["authored_key", "chart_id", "labels", "once", "repeated", "shortened"], template: "Chart {chart_id!r}: every {authored_key!r} series label repeats {repeated}: {labels}.", fix: Some("{once} Tighter labels: {shortened}. Alias the query column for a wide `y: [...]` chart (`SELECT ... AS created`), or shorten the `color:` column's own values for a long-form chart. Keep the repeat only when a label would be unclear without it."), hint: None };
pub const WARN_SESSION_TIME_ZONE_UNSUPPORTED: Code = Code { id: "WARN-SESSION-TIME-ZONE-UNSUPPORTED", level: Level::Warning, title: "Source cannot run queries in the board time zone", params: &["adapter_type", "source", "time_zone"], template: "Source {source!r} ({adapter_type}) has no session time zone, so its queries run in the warehouse's own zone, not the board's {time_zone}.", fix: Some("Convert in the SQL where the board's zone matters, or set regional.time_zone to UTC."), hint: None };
pub const WARN_SINGLE_CHART_REDUNDANT_TITLE: Code = Code { id: "WARN-SINGLE-CHART-REDUNDANT-TITLE", level: Level::Warning, title: "Single-chart board has both a board title and a chart title", params: &["chart_title", "title"], template: "Board title {title!r} sits above a single chart that carries its own title {chart_title!r}; two headers for one chart.", fix: Some("Remove the board's `title:` and keep the chart's `title:`."), hint: None };
pub const WARN_SOURCE_TIME_ZONE_OVERRIDDEN: Code = Code { id: "WARN-SOURCE-TIME-ZONE-OVERRIDDEN", level: Level::Warning, title: "Source time zone is overridden by the board", params: &["source", "source_zone", "time_zone"], template: "Source {source!r} sets time zone {source_zone!r}, but its queries run in the board's {time_zone}.", fix: Some("Remove the source's time zone, or set regional.time_zone to match it."), hint: None };
pub const WARN_SPARK_LABEL_TRUNCATED: Code = Code { id: "WARN-SPARK-LABEL-TRUNCATED", level: Level::Warning, title: "Spark-bar row label was truncated", params: &["chart_id", "truncation_count"], template: "Chart {chart_id!r}: {truncation_count} spark-bar label(s) were truncated; the label column is too narrow to show the full text.", fix: Some("Widen the chart or increase the label column width in the chart style."), hint: None };
pub const WARN_STATIC_PAGINATION_CAPPED: Code = Code { id: "WARN-STATIC-PAGINATION-CAPPED", level: Level::Warning, title: "Static export stopped short of every table page", params: &["chart_id", "page_rows", "rendered_pages", "total_pages", "total_rows"], template: "Table {chart_id!r}: static export pre-rendered {rendered_pages} of {total_pages} pages ({page_rows} rows each, {total_rows} rows total); rows past page {rendered_pages} are not in this file.", fix: Some("Reduce the row count, raise style.pagination.page_rows so fewer pages are needed, give the table a taller slot, or view it on an interactive host (dct serve, Cloud) instead of a static export."), hint: None };
pub const WARN_SUPPORT_TABLE_CELL_OVERFLOW: Code = Code { id: "WARN-SUPPORT-TABLE-CELL-OVERFLOW", level: Level::Warning, title: "Support table cells do not fit", params: &["chart_id", "detail"], template: "Chart {chart_id!r}: support_table cells do not fit ({detail}), so adjacent values run together or the strip is hidden.", fix: Some("Widen the chart, show fewer categories, or shorten the values with a more compact format."), hint: None };
pub const WARN_TABLE_ALIGN_NO_VISIBLE_EFFECT: Code = Code { id: "WARN-TABLE-ALIGN-NO-VISIBLE-EFFECT", level: Level::Warning, title: "Authored align: left on a numeric column has no visible effect", params: &["chart_id", "column"], template: "Table {chart_id!r} column {column!r}: align: left has no visible effect. The digits already start at the cell's left padding, so left and decimal alignment paint identically.", fix: Some("Drop align: left; it isn't doing anything here. Widening the column (an explicit width:) would let the decimal lane center and make the key visible."), hint: None };
pub const WARN_TABLE_COLUMNS_OVERFLOW: Code = Code { id: "WARN-TABLE-COLUMNS-OVERFLOW", level: Level::Warning, title: "Table is wider than its dashboard slot", params: &["available_width", "chart_id", "needed_width"], template: "Table {chart_id!r} overflows its slot: needed {needed_width:.0f}px but only {available_width:.0f}px available.", fix: Some("Widen the table's dashboard slot, reduce the number of columns, or add explicit column widths to control how the table distributes its available space."), hint: None };
pub const WARN_TABLE_CONTENT_TALLER_THAN_WIDE: Code = Code { id: "WARN-TABLE-CONTENT-TALLER-THAN-WIDE", level: Level::Warning, title: "Table text wrapped into a block taller than its column is wide", params: &["cell_count", "chart_id", "column", "column_width", "max_lines"], template: "Table {chart_id!r}: text in the {column!r} column wraps into blocks taller than the column is wide, which usually means it wrapped too much. The worst cell takes {max_lines} lines and {cell_count} cell(s) are that tall, in {column_width:.0f}px allocated to the column.", fix: Some("Give the column more space with `style.columns.{column}.width`, shorten the text, or drop columns from the table."), hint: None };
pub const WARN_TABLE_HEADER_EXTRA_WRAP: Code = Code { id: "WARN-TABLE-HEADER-EXTRA-WRAP", level: Level::Warning, title: "Table column header needs more than two lines", params: &["chart_id", "column", "column_count", "column_width", "header", "lines", "table_width"], template: "Table {chart_id!r}: the {column!r} column header {header!r} needs {lines} lines. Two lines are fine; more is too much. Only {column_width:.0f}px were allocated for this column, in a table of {column_count} columns and {table_width:.0f}px total width.", fix: Some("Shorten the header, or give the column more space: set `style.columns.{column}.width`, drop columns, or widen the table."), hint: None };
pub const WARN_TABLE_NUMERIC_ALIGN_LEFT: Code = Code { id: "WARN-TABLE-NUMERIC-ALIGN-LEFT", level: Level::Warning, title: "Left-aligned numeric column will not decimal-align", params: &["chart_id", "column"], template: "Table {chart_id!r} column {column!r} is align: left on numbers of different width; the digits will not line up down the column.", fix: Some("Drop align: left to keep this column's digits decimal-aligned, the default for numeric columns."), hint: None };
pub const WARN_TABLE_PAGE_SQUEEZED: Code = Code { id: "WARN-TABLE-PAGE-SQUEEZED", level: Level::Warning, title: "Layout slot forced a smaller table page than the table asked for", params: &["chart_id", "drawn_rows", "page_rows", "total_rows"], template: "Table {chart_id!r}: the layout slot fits {drawn_rows} of the {page_rows} rows a page holds ({total_rows} rows total); the rest moved onto later pages.", fix: Some("Give the tile more height (layout height:, a taller row, or fewer siblings sharing the row), or set `page_rows: {drawn_rows}` under `style.pagination` of `charts.{chart_id}` to page at what the slot fits. page_rows is a ceiling: raising it does not make the slot taller."), hint: None };
pub const WARN_TABLE_SCROLL_ROWS_CAPPED: Code = Code { id: "WARN-TABLE-SCROLL-ROWS-CAPPED", level: Level::Warning, title: "Table has too many rows to scroll, so it pages", params: &["chart_id", "max_rows", "total_rows"], template: "Table {chart_id!r}: {total_rows} rows is more than the {max_rows} a scrolling table draws, so it pages instead.", fix: Some("Aggregate or limit the query to at most {max_rows} rows, or set `style.pagination.mode: pages`."), hint: None };
pub const WARN_TABLE_TEXT_TRUNCATED: Code = Code { id: "WARN-TABLE-TEXT-TRUNCATED", level: Level::Warning, title: "Table cell text was truncated", params: &["authored_field", "chart_id", "truncation_count"], template: "Chart {chart_id!r}: truncated text in column(s) {authored_field}: {truncation_count} value(s) were cut with an ellipsis.", fix: Some("Widen the column, shorten the values, or increase the chart width."), hint: None };
pub const WARN_TEMPORAL_SINGLE_POINT: Code = Code { id: "WARN-TEMPORAL-SINGLE-POINT", level: Level::Warning, title: "Temporal line or area chart has only one data point", params: &["chart_id", "chart_type"], template: "Chart {chart_id!r} ({chart_type}): temporal x-axis has exactly one data point; a one-point line/area conveys no trend.", fix: Some("Widen the date filter to include more time periods, or switch to a KPI or stat tile if a single-point value is intentional."), hint: None };
pub const WARN_TOO_MANY_COLOR_CATEGORIES: Code = Code { id: "WARN-TOO-MANY-COLOR-CATEGORIES", level: Level::Warning, title: "Color encoding has more categories than a reader can tell apart", params: &["chart_id", "count", "field", "max_categories"], template: "Chart {chart_id!r}: color encoding on {field!r} yields {count} distinct series, more than the {max_categories} a reader can tell apart.", fix: Some("Cut the categories in the query, not the chart: keep the top N and fold the rest into Other, e.g. `CASE WHEN rank <= 6 THEN category ELSE 'Other' END AS category` over a `RANK() OVER (ORDER BY total DESC)` CTE, then re-aggregate by that column."), hint: None };
pub const WARN_TOO_MANY_X_CATEGORIES: Code = Code { id: "WARN-TOO-MANY-X-CATEGORIES", level: Level::Warning, title: "x-axis has too many distinct values to read", params: &["chart_id", "count", "field", "max_categories"], template: "Chart {chart_id!r}: x field {field!r} has {count} distinct values; labels collide and marks are too thin to read (limit: {max_categories}).", fix: Some("Filter to the top N categories by value, roll up to a coarser grouping, or switch to a scrollable table for wide categorical data."), hint: None };
pub const WARN_TREND_ON_BARS: Code = Code { id: "WARN-TREND-ON-BARS", level: Level::Warning, title: "Trend fitted over bars", params: &["chart_id", "index"], template: "Chart {chart_id!r}: annotation {index} fits a trend to bars. A bar encodes length from zero, so a fitted line over it is a weak read of the pattern.", fix: Some("Draw the column as a line chart (or a line layer) to fit a trend. To keep the bars, thin them with style.marks.bar.band_width (e.g. 0.5) so more of the trend shows between them. If the trend over bars is deliberate, add WARN-TREND-ON-BARS to the chart's warnings_ignore."), hint: None };
