pub const WARN_UNREFERENCED_QUERY: Code = Code { id: "WARN-UNREFERENCED-QUERY", level: Level::Warning, title: "Query is defined but nothing reads it", params: &["query"], template: "Query `{query}` is not used by any chart, variable, text or query; remove it.", fix: Some("Delete the query, or reference it from a chart or variable."), hint: None };
